def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if s == "":
        raise ValueError("empty string")

    factors = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    order = {"d": 0, "h": 1, "m": 2, "s": 3}

    total = 0
    i = 0
    last = -1
    n = len(s)

    while i < n:
        start = i
        while i < n and "0" <= s[i] <= "9":
            i += 1
        if i == start:
            raise ValueError("expected digits")
        if i >= n:
            raise ValueError("expected unit")

        unit = s[i]
        if unit not in order:
            raise ValueError(f"unknown unit: {unit!r}")

        unit_index = order[unit]
        if unit_index == last:
            raise ValueError(f"repeated unit: {unit!r}")
        if unit_index < last:
            raise ValueError(f"out-of-order unit: {unit!r}")
        last = unit_index

        num = int(s[start:i])
        i += 1
        total += num * factors[unit]

    return total
