import heapq

def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps)
    for reqs in deps.values():
        nodes.update(reqs)

    indegree = {n: 0 for n in nodes}
    children = {n: [] for n in nodes}

    for x, reqs in deps.items():
        for r in set(reqs):
            children[r].append(x)
            indegree[x] += 1

    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in children[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(heap, v)

    if len(order) != len(nodes):
        raise ValueError("cycle detected")

    return order
```

