def wildcard_match(s: str, p: str) -> bool:
    n = len(s)
    prev = [False] * (n + 1)
    prev[0] = True

    for ch in p:
        cur = [False] * (n + 1)
        cur[0] = prev[0] if ch == '*' else False

        if ch == '*':
            for j in range(1, n + 1):
                cur[j] = cur[j - 1] or prev[j]
        elif ch == '?':
            for j in range(1, n + 1):
                cur[j] = prev[j - 1]
        else:
            for j in range(1, n + 1):
                cur[j] = prev[j - 1] if s[j - 1] == ch else False

        prev = cur

    return prev[n]
