import heapq

def shortest_paths(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    dist = [float('inf')] * n
    if n == 0:
        return []

    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    dist[src] = 0
    pq = [(0, src)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))

    return [-1 if d == float('inf') else d for d in dist]
