from collections import Counter

def sliding_median(nums, k):
    if k <= 0:
        return []
    n = len(nums)
    if n < k:
        return []

    lo, hi = [], []          # lo: max-heap (negated) lower half; hi: min-heap upper half
    removed = Counter()      # lazy deletions
    cnt_lo = 0               # valid elements in lo
    cnt_hi = 0               # valid elements in hi

    def clean_lo():
        while lo and removed[-lo[0]] > 0:
            removed[-lo[0]] -= 1
            if removed[-lo[0]] == 0:
                del removed[-lo[0]]
            heapq.heappop(lo)

    def clean_hi():
        while hi and removed[hi[0]] > 0:
            removed[hi[0]] -= 1
            if removed[hi[0]] == 0:
                del removed[hi[0]]
            heapq.heappop(hi)

    def add(x):
        nonlocal cnt_lo, cnt_hi
        clean_lo()
        if cnt_lo == 0 or x <= -lo[0]:
            heapq.heappush(lo, -x)
            cnt_lo += 1
        else:
            heapq.heappush(hi, x)
            cnt_hi += 1
        if cnt_lo > cnt_hi + 1:
            clean_lo()
            v = -heapq.heappop(lo)
            cnt_lo -= 1
            heapq.heappush(hi, v)
            cnt_hi += 1
        elif cnt_lo < cnt_hi:
            clean_hi()
            v = heapq.heappop(hi)
            cnt_hi -= 1
            heapq.heappush(lo, -v)
            cnt_lo += 1

    def delete(x):
        nonlocal cnt_lo, cnt_hi
        clean_lo()
        clean_hi()
        if lo and x <= -lo[0]:
            removed[x] += 1
            cnt_lo -= 1
        else:
            removed[x] += 1
            cnt_hi -= 1

    def median():
        clean_lo()
        clean_hi()
        if cnt_lo > cnt_hi:
            return float(-lo[0])
        return (-lo[0] + hi[0]) / 2.0

    for i in range(k):
        add(nums[i])

    res = []
    for i in range(n - k + 1):
        res.append(median())
        if i + k < n:
            delete(nums[i])
            add(nums[i + k])
    return res
